import zipfile, re
with zipfile.ZipFile('/root/project_proposal_ready.hwpx', 'r') as zf:
    print('Archive entries:', zf.namelist()[:5], '...')
    for name in zf.namelist():
        if name.endswith('.xml'):
            c = zf.read(name).decode('utf-8')
            placeholders = re.findall(r'\{\{[^}]+\}\}', c)
            if placeholders:
                print(f'FAIL: {name} has placeholders: {placeholders}')
            if '개월' in c:
                spans = re.findall(r'\(\d+개월\)', c)
                print(f'{name}: month spans = {spans}')
            # Check budget has no commas
            if '₩' in c:
                budgets = re.findall(r'₩[\d,]+', c)
                print(f'{name}: budget values = {budgets}')
                for b in budgets:
                    if ',' in b:
                        print(f'FAIL: Budget still has commas: {b}')
print('Verification done')"

python3 -c "
import zipfile
with zipfile.ZipFile('/root/project_proposal_ready.hwpx', 'r') as zf:
    print('ZIP entries:')
    for i, info in enumerate(zf.infolist()):
        comp = 'STORED (uncompressed)' if info.compress_type == 0 else f'DEFLATED ({info.compress_type})'
        print(f'  {i}: {info.filename} - {comp}')

    if zf.infolist()[0].filename == 'mimetype':
        print('\nSUCCESS: mimetype is the first entry')
        if zf.infolist()[0].compress_type == 0:
            print('SUCCESS: mimetype is uncompressed (STORED)')
        else:
            print('FAIL: mimetype is compressed')
    else:
        print(f'FAIL: First entry is {zf.infolist()[0].filename}')
"

